-- Sample seed data: organizations, resources and declared maximum claims.
-- Requests are NOT seeded: they are created through the API or generated by
-- the (clearly labelled) simulation workload generator.

INSERT INTO organizations (name, org_type, location, contact_info) VALUES
  ('City General Hospital',     'HOSPITAL',    'Dehradun', 'ops@citygeneral.example'),
  ('Riverside Medical Centre',  'HOSPITAL',    'Haridwar', 'ops@riverside.example'),
  ('North Relief Shelter',      'SHELTER',     'Rishikesh', 'shelter-north@example.org'),
  ('East Community Shelter',    'SHELTER',     'Roorkee',  'shelter-east@example.org'),
  ('Rapid Response Team Alpha', 'RESCUE_TEAM', 'Dehradun', 'alpha@rescue.example'),
  ('Rapid Response Team Bravo', 'RESCUE_TEAM', 'Haridwar', 'bravo@rescue.example');

-- total = available + allocated must hold (the CHECK constraint enforces it).
INSERT INTO resources (name, category, total_quantity, available_quantity, allocated_quantity, reusable, location) VALUES
  ('Ambulances',     'AMBULANCE',     20,   20, 0, TRUE,  'Central Depot'),
  ('Hospital Beds',  'HOSPITAL_BED', 100,  100, 0, TRUE,  'Regional Pool'),
  ('Medical Staff',  'MEDICAL_STAFF', 40,   40, 0, TRUE,  'Regional Pool'),
  ('Medicine Kits',  'MEDICINE',     500,  500, 0, FALSE, 'Central Warehouse'),
  ('Food Packets',   'FOOD',        2000, 2000, 0, FALSE, 'Central Warehouse'),
  ('Water Supplies', 'WATER',       3000, 3000, 0, FALSE, 'Central Warehouse');

-- Declared maximum claim per (organization, resource): the Banker's "Max" matrix.
-- Only organizations that could plausibly need a resource declare a claim.
INSERT INTO organization_claims (organization_id, resource_id, max_claim)
SELECT o.id, r.id, c.max_claim
FROM (VALUES
  ('City General Hospital',     'Ambulances',      6), ('City General Hospital',     'Hospital Beds', 40),
  ('City General Hospital',     'Medical Staff',  15), ('City General Hospital',     'Medicine Kits', 200),
  ('Riverside Medical Centre',  'Ambulances',      5), ('Riverside Medical Centre',  'Hospital Beds', 30),
  ('Riverside Medical Centre',  'Medical Staff',  12), ('Riverside Medical Centre',  'Medicine Kits', 150),
  ('North Relief Shelter',      'Food Packets',  800), ('North Relief Shelter',      'Water Supplies', 1200),
  ('East Community Shelter',    'Food Packets',  700), ('East Community Shelter',    'Water Supplies', 1000),
  ('Rapid Response Team Alpha', 'Ambulances',      8), ('Rapid Response Team Alpha', 'Medical Staff', 10),
  ('Rapid Response Team Bravo', 'Ambulances',      7), ('Rapid Response Team Bravo', 'Medical Staff',  8)
) AS c(org_name, res_name, max_claim)
JOIN organizations o ON o.name = c.org_name
JOIN resources     r ON r.name = c.res_name;

-- Initial history entry per resource, so the audit trail starts complete.
INSERT INTO resource_history (resource_id, action, quantity_change, available_before, available_after, note)
SELECT id, 'CREATE', total_quantity, 0, available_quantity, 'Seed data'
FROM resources;
